namespace BCSMS.Domain.Common;

/// <summary>
/// Base class for all domain entities providing identity and audit timestamps.
/// </summary>
public abstract class BaseEntity
{
    public Guid Id { get; private set; }
    public DateTime CreatedAt { get; private set; }
    public DateTime? UpdatedAt { get; protected set; }

    protected BaseEntity()
    {
        // For EF Core materialization
    }

    protected BaseEntity(Guid id)
    {
        if (id == Guid.Empty)
            throw new ArgumentException("Entity Id cannot be empty.", nameof(id));

        Id = id;
        CreatedAt = DateTime.UtcNow;
    }
}

namespace BCSMS.Domain.Common;

/// <summary>
/// Exception thrown when a domain business rule is violated.
/// Intended to be caught at the API layer and mapped to HTTP 400/422.
/// </summary>
public class DomainException : Exception
{
    public DomainException(string message)
        : base(message)
    {
    }

    public DomainException(string message, Exception innerException)
        : base(message, innerException)
    {
    }
}

namespace BCSMS.Domain.Enums;

/// <summary>
/// Represents the lifecycle status of a service request.
/// </summary>
public enum RequestStatus
{
    New = 0,
    Reviewing = 1,
    Assigned = 2,
    InProgress = 3,
    Resolved = 4,
    Closed = 5,
    Rejected = 6,
    Cancelled = 7
}

namespace BCSMS.Domain.Enums;

/// <summary>
/// Categories of municipal service requests.
/// </summary>
public enum RequestCategory
{
    RoadDamage = 0,
    WasteCleaning = 1,
    StreetLighting = 2,
    ParkGarden = 3,
    Flooding = 4,
    NoiseComplaint = 5,
    SocialAssistance = 6,
    Other = 7
}

namespace BCSMS.Domain.Enums;

/// <summary>
/// Priority levels for service requests.
/// </summary>
public enum Priority
{
    Low = 0,
    Medium = 1,
    High = 2,
    Critical = 3
}

namespace BCSMS.Domain.Enums;

/// <summary>
/// System user roles determining authorization scope.
/// </summary>
public enum UserRole
{
    Citizen = 0,
    Employee = 1,
    Manager = 2,
    Admin = 3
}

using BCSMS.Domain.Common;

namespace BCSMS.Domain.ValueObjects;

/// <summary>
/// Represents a geographic location with coordinates and an optional human-readable address.
/// </summary>
public record Location
{
    public double Latitude { get; }
    public double Longitude { get; }
    public string? AddressText { get; }

    public Location(double latitude, double longitude, string? addressText = null)
    {
        if (latitude < -90 || latitude > 90)
            throw new DomainException($"Latitude must be between -90 and 90. Got: {latitude}");

        if (longitude < -180 || longitude > 180)
            throw new DomainException($"Longitude must be between -180 and 180. Got: {longitude}");

        Latitude = latitude;
        Longitude = longitude;
        AddressText = addressText;
    }
}

using BCSMS.Domain.Common;

namespace BCSMS.Domain.ValueObjects;

/// <summary>
/// Represents a person's full name.
/// </summary>
public record FullName
{
    public string FirstName { get; }
    public string LastName { get; }

    public FullName(string firstName, string lastName)
    {
        if (string.IsNullOrWhiteSpace(firstName))
            throw new DomainException("First name is required.");

        if (string.IsNullOrWhiteSpace(lastName))
            throw new DomainException("Last name is required.");

        FirstName = firstName.Trim();
        LastName = lastName.Trim();
    }

    public override string ToString() => $"{FirstName} {LastName}";
}

using BCSMS.Domain.Common;

namespace BCSMS.Domain.ValueObjects;

/// <summary>
/// Represents a user's contact information.
/// </summary>
public record ContactInfo
{
    public string Email { get; }
    public string PhoneNumber { get; }

    public ContactInfo(string email, string phoneNumber)
    {
        if (string.IsNullOrWhiteSpace(email))
            throw new DomainException("Email is required.");

        Email = email.Trim().ToLowerInvariant();
        PhoneNumber = phoneNumber?.Trim() ?? string.Empty;
    }
}

using BCSMS.Domain.Common;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Represents a municipal department responsible for handling service requests.
/// Aggregate root.
/// </summary>
public class Department : BaseEntity
{
    public string Name { get; private set; } = default!;
    public string? Description { get; private set; }
    public bool IsActive { get; private set; }

    private Department() : base()
    {
        // For EF Core
    }

    public Department(Guid id, string name, string? description = null)
        : base(id)
    {
        SetName(name);
        Description = description?.Trim();
        IsActive = true;
    }

    /// <summary>
    /// Updates the department's name and description.
    /// </summary>
    public void Update(string name, string? description)
    {
        SetName(name);
        Description = description?.Trim();
        UpdatedAt = DateTime.UtcNow;
    }

    public void Activate()
    {
        IsActive = true;
        UpdatedAt = DateTime.UtcNow;
    }

    public void Deactivate()
    {
        IsActive = false;
        UpdatedAt = DateTime.UtcNow;
    }

    private void SetName(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
            throw new DomainException("Department name is required.");

        Name = name.Trim();
    }
}

using BCSMS.Domain.Common;
using BCSMS.Domain.Enums;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Records a single status transition on a service request.
/// Child entity of the ServiceRequest aggregate — cannot be created externally.
/// </summary>
public class StatusHistoryEntry : BaseEntity
{
    public Guid ServiceRequestId { get; private set; }
    public RequestStatus OldStatus { get; private set; }
    public RequestStatus NewStatus { get; private set; }
    public string? Note { get; private set; }
    public Guid ChangedByUserId { get; private set; }
    public DateTime ChangedAt { get; private set; }

    private StatusHistoryEntry() : base()
    {
        // For EF Core
    }

    internal StatusHistoryEntry(
        Guid id,
        Guid serviceRequestId,
        RequestStatus oldStatus,
        RequestStatus newStatus,
        Guid changedByUserId,
        string? note = null)
        : base(id)
    {
        ServiceRequestId = serviceRequestId;
        OldStatus = oldStatus;
        NewStatus = newStatus;
        ChangedByUserId = changedByUserId;
        Note = note?.Trim();
        ChangedAt = DateTime.UtcNow;
    }
}

using BCSMS.Domain.Common;

namespace BCSMS.Domain.Entities;

/// <summary>
/// A comment or note attached to a service request.
/// Child entity of the ServiceRequest aggregate — cannot be created externally.
/// </summary>
public class Comment : BaseEntity
{
    public Guid ServiceRequestId { get; private set; }
    public string Content { get; private set; } = default!;
    public Guid CreatedByUserId { get; private set; }

    private Comment() : base()
    {
        // For EF Core
    }

    internal Comment(Guid id, Guid serviceRequestId, string content, Guid createdByUserId)
        : base(id)
    {
        if (string.IsNullOrWhiteSpace(content))
            throw new DomainException("Comment content is required.");

        ServiceRequestId = serviceRequestId;
        Content = content.Trim();
        CreatedByUserId = createdByUserId;
    }
}

using BCSMS.Domain.Common;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Metadata for a file attached to a service request.
/// The actual file is stored by Infrastructure — the domain only tracks metadata.
/// Child entity of the ServiceRequest aggregate — cannot be created externally.
/// </summary>
public class Attachment : BaseEntity
{
    public Guid ServiceRequestId { get; private set; }
    public string FileName { get; private set; } = default!;
    public string ContentType { get; private set; } = default!;
    public long FileSizeInBytes { get; private set; }
    public string StoragePath { get; private set; } = default!;
    public Guid UploadedByUserId { get; private set; }
    public DateTime UploadedAt { get; private set; }

    private Attachment() : base()
    {
        // For EF Core
    }

    internal Attachment(
        Guid id,
        Guid serviceRequestId,
        string fileName,
        string contentType,
        long fileSizeInBytes,
        string storagePath,
        Guid uploadedByUserId)
        : base(id)
    {
        if (string.IsNullOrWhiteSpace(fileName))
            throw new DomainException("Attachment file name is required.");

        if (string.IsNullOrWhiteSpace(contentType))
            throw new DomainException("Attachment content type is required.");

        if (fileSizeInBytes <= 0)
            throw new DomainException("Attachment file size must be greater than zero.");

        if (string.IsNullOrWhiteSpace(storagePath))
            throw new DomainException("Attachment storage path is required.");

        ServiceRequestId = serviceRequestId;
        FileName = fileName.Trim();
        ContentType = contentType.Trim();
        FileSizeInBytes = fileSizeInBytes;
        StoragePath = storagePath.Trim();
        UploadedByUserId = uploadedByUserId;
        UploadedAt = DateTime.UtcNow;
    }
}

using BCSMS.Domain.Common;
using BCSMS.Domain.Enums;
using BCSMS.Domain.ValueObjects;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Represents any system user: citizen, employee, manager, or admin.
/// Aggregate root. Role determines authorization scope.
/// </summary>
public class User : BaseEntity
{
    public FullName Name { get; private set; } = default!;
    public ContactInfo Contact { get; private set; } = default!;
    public UserRole Role { get; private set; }

    /// <summary>
    /// The department this user belongs to. Required for Employee and Manager roles.
    /// Must be null for Citizen and Admin roles.
    /// </summary>
    public Guid? DepartmentId { get; private set; }

    public bool IsActive { get; private set; }

    private User() : base()
    {
        // For EF Core
    }

    public User(Guid id, FullName name, ContactInfo contact, UserRole role, Guid? departmentId = null)
        : base(id)
    {
        Name = name ?? throw new DomainException("User name is required.");
        Contact = contact ?? throw new DomainException("User contact information is required.");
        Role = role;
        IsActive = true;

        ValidateDepartmentForRole(role, departmentId);
        DepartmentId = departmentId;
    }

    /// <summary>
    /// Updates the user's name and contact information.
    /// </summary>
    public void UpdateProfile(FullName name, ContactInfo contact)
    {
        Name = name ?? throw new DomainException("User name is required.");
        Contact = contact ?? throw new DomainException("User contact information is required.");
        UpdatedAt = DateTime.UtcNow;
    }

    /// <summary>
    /// Changes the user's role and department assignment.
    /// </summary>
    public void ChangeRole(UserRole newRole, Guid? departmentId)
    {
        ValidateDepartmentForRole(newRole, departmentId);
        Role = newRole;
        DepartmentId = departmentId;
        UpdatedAt = DateTime.UtcNow;
    }

    public void Activate()
    {
        IsActive = true;
        UpdatedAt = DateTime.UtcNow;
    }

    public void Deactivate()
    {
        IsActive = false;
        UpdatedAt = DateTime.UtcNow;
    }

    private static void ValidateDepartmentForRole(UserRole role, Guid? departmentId)
    {
        bool requiresDepartment = role is UserRole.Employee or UserRole.Manager;

        if (requiresDepartment && departmentId is null)
            throw new DomainException($"A {role} must be assigned to a department.");

        if (!requiresDepartment && departmentId is not null)
            throw new DomainException($"A {role} must not be assigned to a department.");
    }
}

using BCSMS.Domain.Common;
using BCSMS.Domain.Enums;
using BCSMS.Domain.ValueObjects;

namespace BCSMS.Domain.Entities;

/// <summary>
/// Represents a citizen's request for a municipal service.
/// Aggregate root containing status history, comments, and attachment metadata.
/// Encapsulates the full request lifecycle state machine.
/// </summary>
public class ServiceRequest : BaseEntity
{
    public string Title { get; private set; } = default!;
    public string? Description { get; private set; }
    public RequestCategory Category { get; private set; }
    public RequestStatus Status { get; private set; }
    public Priority? Priority { get; private set; }
    public Location? Location { get; private set; }

    /// <summary>
    /// The citizen who created this request. Immutable after creation.
    /// </summary>
    public Guid CitizenId { get; private set; }

    public Guid? AssignedDepartmentId { get; private set; }
    public Guid? AssignedEmployeeId { get; private set; }

    // Encapsulated collections — external code uses the IReadOnlyList properties.
    private readonly List<StatusHistoryEntry> _statusHistory = new();
    private readonly List<Comment> _comments = new();
    private readonly List<Attachment> _attachments = new();

    public IReadOnlyList<StatusHistoryEntry> StatusHistory => _statusHistory.AsReadOnly();
    public IReadOnlyList<Comment> Comments => _comments.AsReadOnly();
    public IReadOnlyList<Attachment> Attachments => _attachments.AsReadOnly();

    private ServiceRequest() : base()
    {
        // For EF Core
    }

    public ServiceRequest(
        Guid id,
        string title,
        RequestCategory category,
        Guid citizenId,
        string? description = null,
        Location? location = null)
        : base(id)
    {
        if (string.IsNullOrWhiteSpace(title))
            throw new DomainException("Service request title is required.");

        if (citizenId == Guid.Empty)
            throw new DomainException("Citizen ID is required.");

        Title = title.Trim();
        Description = description?.Trim();
        Category = category;
        CitizenId = citizenId;
        Location = location;
        Status = RequestStatus.New;
    }

    // ──────────────────────────────────────────────
    // State Machine Transitions
    // ──────────────────────────────────────────────

    /// <summary>
    /// Transitions: New → Reviewing.
    /// A manager or admin begins reviewing the request.
    /// </summary>
    public void Review(Guid changedByUserId)
    {
        EnsureValidTransition(RequestStatus.New, RequestStatus.Reviewing);
        TransitionTo(RequestStatus.Reviewing, changedByUserId);
    }

    /// <summary>
    /// Transitions: Reviewing → Assigned.
    /// Assigns the request to a department and optionally to an employee.
    /// Priority must be provided.
    /// </summary>
    public void Assign(Guid departmentId, Guid? employeeId, Priority priority, Guid changedByUserId)
    {
        EnsureValidTransition(RequestStatus.Reviewing, RequestStatus.Assigned);

        if (departmentId == Guid.Empty)
            throw new DomainException("Department ID is required for assignment.");

        AssignedDepartmentId = departmentId;
        AssignedEmployeeId = employeeId;
        Priority = priority;
        TransitionTo(RequestStatus.Assigned, changedByUserId);
    }

    /// <summary>
    /// Transitions: Assigned → InProgress.
    /// The assigned employee begins working on the request.
    /// </summary>
    public void StartProgress(Guid changedByUserId)
    {
        EnsureValidTransition(RequestStatus.Assigned, RequestStatus.InProgress);
        TransitionTo(RequestStatus.InProgress, changedByUserId);
    }

    /// <summary>
    /// Transitions: InProgress → Resolved.
    /// The employee has completed the work.
    /// </summary>
    public void Resolve(Guid changedByUserId, string? note = null)
    {
        EnsureValidTransition(RequestStatus.InProgress, RequestStatus.Resolved);
        TransitionTo(RequestStatus.Resolved, changedByUserId, note);
    }

    /// <summary>
    /// Transitions: Resolved → Closed.
    /// A manager or admin confirms the resolution.
    /// </summary>
    public void Close(Guid changedByUserId, string? note = null)
    {
        EnsureValidTransition(RequestStatus.Resolved, RequestStatus.Closed);
        TransitionTo(RequestStatus.Closed, changedByUserId, note);
    }

    /// <summary>
    /// Transitions: Resolved → InProgress.
    /// Resolution was not satisfactory — reopen for further work.
    /// </summary>
    public void Reopen(Guid changedByUserId, string? note = null)
    {
        EnsureValidTransition(RequestStatus.Resolved, RequestStatus.InProgress);
        TransitionTo(RequestStatus.InProgress, changedByUserId, note);
    }

    /// <summary>
    /// Transitions: New or Reviewing → Rejected.
    /// The request is denied by staff.
    /// </summary>
    public void Reject(Guid changedByUserId, string? note = null)
    {
        if (Status is not (RequestStatus.New or RequestStatus.Reviewing))
            throw new DomainException(
                $"Cannot reject a request in '{Status}' status. Only 'New' or 'Reviewing' requests can be rejected.");

        TransitionTo(RequestStatus.Rejected, changedByUserId, note);
    }

    /// <summary>
    /// Transitions: New, Reviewing, or Assigned → Cancelled.
    /// The citizen withdraws the request, or a manager cancels it before work starts.
    /// </summary>
    public void Cancel(Guid changedByUserId)
    {
        if (Status is not (RequestStatus.New or RequestStatus.Reviewing or RequestStatus.Assigned))
            throw new DomainException(
                $"Cannot cancel a request in '{Status}' status. " +
                "Only requests in 'New', 'Reviewing', or 'Assigned' status can be cancelled.");

        TransitionTo(RequestStatus.Cancelled, changedByUserId);
    }

    // ──────────────────────────────────────────────
    // Child Entity Management
    // ──────────────────────────────────────────────

    /// <summary>
    /// Adds a comment to the request. Not allowed on terminal-state requests.
    /// </summary>
    public Comment AddComment(string content, Guid createdByUserId)
    {
        EnsureNotInTerminalState("add a comment");

        var comment = new Comment(Guid.NewGuid(), Id, content, createdByUserId);
        _comments.Add(comment);
        UpdatedAt = DateTime.UtcNow;
        return comment;
    }

    /// <summary>
    /// Adds attachment metadata to the request. Not allowed on terminal-state requests.
    /// </summary>
    public Attachment AddAttachment(
        string fileName,
        string contentType,
        long fileSizeInBytes,
        string storagePath,
        Guid uploadedByUserId)
    {
        EnsureNotInTerminalState("add an attachment");

        var attachment = new Attachment(
            Guid.NewGuid(), Id, fileName, contentType, fileSizeInBytes, storagePath, uploadedByUserId);
        _attachments.Add(attachment);
        UpdatedAt = DateTime.UtcNow;
        return attachment;
    }

    // ──────────────────────────────────────────────
    // Detail Updates
    // ──────────────────────────────────────────────

    /// <summary>
    /// Updates mutable details of the request. Not allowed on terminal-state requests.
    /// </summary>
    public void UpdateDetails(string? title = null, string? description = null,
        RequestCategory? category = null, Location? location = null)
    {
        EnsureNotInTerminalState("update details");

        if (title is not null)
        {
            if (string.IsNullOrWhiteSpace(title))
                throw new DomainException("Service request title cannot be empty.");

            Title = title.Trim();
        }

        if (description is not null)
            Description = description.Trim();

        if (category.HasValue)
            Category = category.Value;

        if (location is not null)
            Location = location;

        UpdatedAt = DateTime.UtcNow;
    }

    /// <summary>
    /// Sets or updates the priority. Not allowed on terminal-state requests.
    /// </summary>
    public void SetPriority(Priority priority)
    {
        EnsureNotInTerminalState("set priority");
        Priority = priority;
        UpdatedAt = DateTime.UtcNow;
    }

    // ──────────────────────────────────────────────
    // Private Helpers
    // ──────────────────────────────────────────────

    private void TransitionTo(RequestStatus newStatus, Guid changedByUserId, string? note = null)
    {
        var entry = new StatusHistoryEntry(
            Guid.NewGuid(), Id, Status, newStatus, changedByUserId, note);

        _statusHistory.Add(entry);
        Status = newStatus;
        UpdatedAt = DateTime.UtcNow;
    }

    private void EnsureValidTransition(RequestStatus expectedCurrent, RequestStatus target)
    {
        if (Status != expectedCurrent)
            throw new DomainException(
                $"Cannot transition to '{target}' from '{Status}'. Expected current status: '{expectedCurrent}'.");
    }

    private void EnsureNotInTerminalState(string action)
    {
        if (Status is RequestStatus.Closed or RequestStatus.Rejected or RequestStatus.Cancelled)
            throw new DomainException(
                $"Cannot {action} on a request in terminal state '{Status}'.");
    }
}

