namespace BCSMS.Application.Abstractions.Time;

/// <summary>
/// Abstraction for providing the current UTC time.
/// Keeps application and domain operations deterministic and testable.
/// </summary>
public interface IClock
{
    DateTime UtcNow { get; }
}

namespace BCSMS.Application.Common.Exceptions;

/// <summary>
/// Thrown when a requested resource is not found.
/// </summary>
public class NotFoundException : Exception
{
    public NotFoundException(string message)
        : base(message)
    {
    }

    public NotFoundException(string entityName, object key)
        : base($"Entity '{entityName}' with key '{key}' was not found.")
    {
    }
}

namespace BCSMS.Application.Common.Exceptions;

/// <summary>
/// Thrown when an authenticated user is forbidden from performing the operation.
/// </summary>
public class ForbiddenException : Exception
{
    public ForbiddenException(string message)
        : base(message)
    {
    }
}

namespace BCSMS.Application.Common.Exceptions;

/// <summary>
/// Thrown when application request validation fails.
/// </summary>
public class ValidationException : Exception
{
    public ValidationException(string message)
        : base(message)
    {
    }
}

namespace BCSMS.Application.Common.Exceptions;

/// <summary>
/// Thrown when an operation cannot be performed due to the current state of a resource (e.g. inactive user/category).
/// </summary>
public class ApplicationConflictException : Exception
{
    public ApplicationConflictException(string message)
        : base(message)
    {
    }
}

namespace BCSMS.Application.Common.Models;

/// <summary>
/// Generic container for paginated query results.
/// </summary>
public record PagedResult<T>
{
    public IReadOnlyList<T> Items { get; init; } = Array.Empty<T>();
    public int PageNumber { get; init; }
    public int PageSize { get; init; }
    public int TotalCount { get; init; }
    public int TotalPages => PageSize > 0 ? (int)Math.Ceiling(TotalCount / (double)PageSize) : 0;
    public bool HasPreviousPage => PageNumber > 1;
    public bool HasNextPage => PageNumber < TotalPages;

    public PagedResult()
    {
    }

    public PagedResult(IReadOnlyList<T> items, int totalCount, int pageNumber, int pageSize)
    {
        Items = items;
        TotalCount = totalCount;
        PageNumber = pageNumber;
        PageSize = pageSize;
    }
}

