using BCSMS.Application.Abstractions.Security;
using Microsoft.AspNetCore.Identity;

namespace BCSMS.Infrastructure.Security;

/// <summary>
/// Password hashing implementation using ASP.NET Core Identity PasswordHasher.
/// Uses standard PBKDF2 with HMAC-SHA256 and secure cryptographic salting.
/// </summary>
public class PasswordHasher : IPasswordHasher
{
    private readonly PasswordHasher<object> _hasher = new();
    private static readonly object DummyUser = new();

    public string HashPassword(string password)
    {
        return _hasher.HashPassword(DummyUser, password);
    }

    public bool VerifyPassword(string password, string passwordHash)
    {
        var result = _hasher.VerifyHashedPassword(DummyUser, passwordHash, password);
        return result is PasswordVerificationResult.Success or PasswordVerificationResult.SuccessRehashNeeded;
    }
}

namespace BCSMS.Infrastructure.Security;

/// <summary>
/// Configuration options for JSON Web Token generation and verification.
/// </summary>
public class JwtSettings
{
    public const string SectionName = "JwtSettings";

    public string Issuer { get; set; } = "BCSMS.API";
    public string Audience { get; set; } = "BCSMS.Web";
    public string Secret { get; set; } = "BursaCityServiceManagementSystemSafeDevelopmentKey2026!";
    public int ExpiryMinutes { get; set; } = 120;
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using BCSMS.Application.Abstractions.Security;
using BCSMS.Application.Abstractions.Time;
using BCSMS.Domain.Entities;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.Tokens;

namespace BCSMS.Infrastructure.Security;

/// <summary>
/// Generates signed JWT access tokens containing user identity and role claims.
/// </summary>
public class JwtTokenGenerator : IJwtTokenGenerator
{
    private readonly JwtSettings _jwtSettings;
    private readonly IClock _clock;

    public JwtTokenGenerator(IOptions<JwtSettings> jwtOptions, IClock clock)
    {
        _jwtSettings = jwtOptions.Value;
        _clock = clock;
    }

    public (string Token, DateTime ExpiresAt) GenerateToken(User user)
    {
        var expiresAt = _clock.UtcNow.AddMinutes(_jwtSettings.ExpiryMinutes);

        var claims = new List<Claim>
        {
            new(JwtRegisteredClaimNames.Sub, user.Id.ToString()),
            new(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new(JwtRegisteredClaimNames.Email, user.Contact.Email),
            new(ClaimTypes.Email, user.Contact.Email),
            new(ClaimTypes.Role, user.Role.ToString()),
            new("role", user.Role.ToString()),
            new(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
        };

        var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_jwtSettings.Secret));
        var credentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

        var tokenDescriptor = new JwtSecurityToken(
            issuer: _jwtSettings.Issuer,
            audience: _jwtSettings.Audience,
            claims: claims,
            notBefore: _clock.UtcNow,
            expires: expiresAt,
            signingCredentials: credentials);

        var tokenHandler = new JwtSecurityTokenHandler();
        var token = tokenHandler.WriteToken(tokenDescriptor);

        return (token, expiresAt);
    }
}

