    {
        _clock = clock;
    }

    public (string Token, DateTime ExpiresAt) GenerateToken(User user)
    {
        var expiresAt = _clock.UtcNow.AddMinutes(60);
        var token = $"fake_jwt_token_for_{user.Id}";
        return (token, expiresAt);
    }
}

