        RequestStatus? statusFilter,
        Guid? categoryId,
        Guid? departmentId,
        Priority? priority,
        int pageNumber,
        int pageSize,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Retrieves paginated summary DTOs for requests assigned to a specific employee.
    /// </summary>
