namespace BCSMS.Infrastructure.Persistence.Repositories;

public class CategoryRepository : ICategoryRepository
{
    private readonly BcsmsDbContext _dbContext;

    public CategoryRepository(BcsmsDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<Category?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Categories
            .AsNoTracking()
            .FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
    }

    public async Task<IReadOnlyList<CategoryLookupDto>> GetActiveLookupAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Categories
            .AsNoTracking()
            .Where(c => c.IsActive)
            .OrderBy(c => c.Name)
            .Select(c => new CategoryLookupDto(c.Id, c.Name, c.Description))
            .ToListAsync(cancellationToken);
    }
}

using BCSMS.Application.Abstractions.Persistence;
using BCSMS.Application.Reference;
using BCSMS.Domain.Entities;
using Microsoft.EntityFrameworkCore;

namespace BCSMS.Infrastructure.Persistence.Repositories;

public class DepartmentRepository : IDepartmentRepository
{
    private readonly BcsmsDbContext _dbContext;

    public DepartmentRepository(BcsmsDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<Department?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Departments
            .AsNoTracking()
            .FirstOrDefaultAsync(d => d.Id == id, cancellationToken);
    }

    public async Task<IReadOnlyList<DepartmentLookupDto>> GetActiveLookupAsync(CancellationToken cancellationToken = default)
    {
        return await _dbContext.Departments
            .AsNoTracking()
            .Where(d => d.IsActive)
            .OrderBy(d => d.Name)
            .Select(d => new DepartmentLookupDto(d.Id, d.Name))
            .ToListAsync(cancellationToken);
    }
}

using BCSMS.Application.Abstractions.Persistence;
using BCSMS.Application.Reference;
using BCSMS.Domain.Entities;
using BCSMS.Domain.Enums;
using Microsoft.EntityFrameworkCore;

namespace BCSMS.Infrastructure.Persistence.Repositories;

public class UserRepository : IUserRepository
{
    private readonly BcsmsDbContext _dbContext;

    public UserRepository(BcsmsDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<User?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _dbContext.Users
            .AsNoTracking()
            .FirstOrDefaultAsync(u => u.Id == id, cancellationToken);
    }

    public async Task<User?> GetByEmailAsync(string email, CancellationToken cancellationToken = default)
    {
        var normalizedEmail = email.Trim().ToLowerInvariant();

        return await _dbContext.Users
            .AsNoTracking()
            .FirstOrDefaultAsync(u => u.Contact.Email == normalizedEmail, cancellationToken);
    }

    public async Task<bool> ExistsByEmailAsync(string email, CancellationToken cancellationToken = default)
    {
        var normalizedEmail = email.Trim().ToLowerInvariant();

        return await _dbContext.Users
            .AnyAsync(u => u.Contact.Email == normalizedEmail, cancellationToken);
    }

    public async Task AddAsync(User user, CancellationToken cancellationToken = default)
    {
        await _dbContext.Users.AddAsync(user, cancellationToken);
        await _dbContext.SaveChangesAsync(cancellationToken);
    }

    public async Task<IReadOnlyList<EmployeeLookupDto>> GetActiveEmployeesByDepartmentLookupAsync(
        Guid departmentId,
        CancellationToken cancellationToken = default)
    {
        return await _dbContext.Users
            .AsNoTracking()
            .Where(u => u.IsActive && u.Role == UserRole.Employee && u.DepartmentId == departmentId)
            .OrderBy(u => u.Name.FirstName)
            .ThenBy(u => u.Name.LastName)
            .Select(u => new EmployeeLookupDto(
                u.Id,
                u.Name.FirstName + " " + u.Name.LastName,
                u.Contact.Email))
            .ToListAsync(cancellationToken);
    }
}

using BCSMS.Application.Abstractions.Persistence;
using BCSMS.Application.Reference;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace BCSMS.API.Controllers;

[ApiController]
[Route("api")]
public class ReferenceDataController : ControllerBase
{
    private readonly ICategoryRepository _categoryRepository;
    private readonly IDepartmentRepository _departmentRepository;
    private readonly IUserRepository _userRepository;

    public ReferenceDataController(
        ICategoryRepository categoryRepository,
        IDepartmentRepository departmentRepository,
        IUserRepository userRepository)
    {
        _categoryRepository = categoryRepository;
        _departmentRepository = departmentRepository;
        _userRepository = userRepository;
    }

    /// <summary>
    /// Retrieves active service request categories for dropdown selection.
    /// </summary>
    [HttpGet("categories")]
    [Authorize]
    [ProducesResponseType(typeof(IReadOnlyList<CategoryLookupDto>), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> GetCategories(CancellationToken cancellationToken)
    {
        var categories = await _categoryRepository.GetActiveLookupAsync(cancellationToken);
        return Ok(categories);
    }

    /// <summary>
    /// Retrieves active municipal departments for assignment and filtering.
    /// </summary>
    [HttpGet("departments")]
    [Authorize(Roles = "Manager,Admin")]
    [ProducesResponseType(typeof(IReadOnlyList<DepartmentLookupDto>), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status403Forbidden)]
    public async Task<IActionResult> GetDepartments(CancellationToken cancellationToken)
    {
        var departments = await _departmentRepository.GetActiveLookupAsync(cancellationToken);
        return Ok(departments);
    }

    /// <summary>
    /// Retrieves active employees belonging to the specified department.
    /// </summary>
    [HttpGet("departments/{departmentId:guid}/employees")]
    [Authorize(Roles = "Manager,Admin")]
    [ProducesResponseType(typeof(IReadOnlyList<EmployeeLookupDto>), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status403Forbidden)]
    public async Task<IActionResult> GetDepartmentEmployees(
        [FromRoute] Guid departmentId,
        CancellationToken cancellationToken)
    {
        var employees = await _userRepository.GetActiveEmployeesByDepartmentLookupAsync(departmentId, cancellationToken);
        return Ok(employees);
    }
}

