import axios from 'axios';
import { ProblemDetails } from '../types/auth.types';

export function getErrorMessage(error: unknown): string {
  if (axios.isAxiosError(error)) {
    const data = error.response?.data as ProblemDetails | undefined;
    if (data) {
      if (data.detail && typeof data.detail === 'string') {
        return data.detail;
      }
      if (data.title && typeof data.title === 'string') {
        return data.title;
      }
      if (data.errors && typeof data.errors === 'object') {
        const errorMessages = Object.values(data.errors).flat();
        if (errorMessages.length > 0) {
          return errorMessages.join(' ');
        }
      }
    }

    if (error.response?.status === 401) {
      return 'Oturum süreniz doldu veya giriş bilgileriniz geçersiz.';
    }
    if (error.response?.status === 403) {
      return 'Bu işlemi gerçekleştirmek için yetkiniz bulunmamaktadır.';
    }
    if (error.response?.status === 404) {
      return 'Talep edilen kayıt bulunamadı.';
    }
    if (error.response?.status === 409) {
      return 'İşlem mevcut durumla çakışmaktadır.';
    }
    if (error.response?.status === 422) {
      return 'Geçersiz durum geçişi veya veri kuralı ihlali.';
    }
    if (error.response?.status === 500) {
      return 'Sunucu tarafında beklenmeyen bir hata oluştu. Lütfen tekrar deneyiniz.';
    }
  }

  if (error instanceof Error) {
    return error.message;
  }

  return 'Beklenmeyen bir hata oluştu. Lütfen tekrar deneyiniz.';
}

export function formatDate(dateString?: string | null): string {
  if (!dateString) return '-';
  try {
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString;
    return new Intl.DateTimeFormat('tr-TR', {
      day: '2-digit',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    }).format(date);
  } catch {
    return dateString;
  }
}

export function formatShortDate(dateString?: string | null): string {
  if (!dateString) return '-';
  try {
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return dateString;
    return new Intl.DateTimeFormat('tr-TR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    }).format(date);
  } catch {
    return dateString;
  }
}

export function formatCoordinates(lat?: number | null, lng?: number | null): string {
  if (lat == null || lng == null) return 'Konum belirtilmemiş';
  return `${lat.toFixed(4)}° K, ${lng.toFixed(4)}° D`;
}

import axios from 'axios';

const baseURL = import.meta.env.VITE_API_BASE_URL || '';

export const apiClient = axios.create({
  baseURL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor: attach bearer token from sessionStorage
apiClient.interceptors.request.use((config) => {
  const token = sessionStorage.getItem('bcsms_access_token');
  if (token && config.headers) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// Response interceptor: handle 401 Unauthorized globally
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      sessionStorage.removeItem('bcsms_access_token');
      sessionStorage.removeItem('bcsms_user');
      // Dispatch custom event so AuthContext and QueryClient can synchronize
      window.dispatchEvent(new CustomEvent('bcsms_unauthorized'));
    }
    return Promise.reject(error);
  }
);

import { apiClient } from './axios';
import { LoginResponse, RegisterResponse } from '../types/auth.types';

export interface LoginPayload {
  email: string;
  password: string;
}

export interface RegisterPayload {
  firstName: string;
  lastName: string;
  email: string;
  phoneNumber?: string;
  password: string;
}

export const authApi = {
  login: async (payload: LoginPayload): Promise<LoginResponse> => {
    const response = await apiClient.post<LoginResponse>('/api/auth/login', payload);
    return response.data;
  },

